inline uint64_t pack(const State&s){uint64_t x=0;for(int i=0;i<12;i++)x|=((uint64_t)s[i])<<(3*i);return x;} inline State unpack(uint64_t x){State s{};for(int i=0;i<12;i++)s[i]=(x>>(3*i))&7;return s;}
inline uint64_t tpack(const State&s,int a,int eps){State t{};for(int i=0;i<12;i++){int j=(eps*i+a)%12;if(j<0)j+=12;t[j]=s[i];}return pack(t);} unordered_map<uint64_t,uint64_t> CC; inline uint64_t canon(const State&s){uint64_t raw=pack(s);auto it=CC.find(raw);if(it!=CC.end())return it->second;uint64_t b=raw;for(int eps:{1,-1})for(int a=0;a<12;a++)b=min(b,tpack(s,a,eps));CC[raw]=b;return b;} inline uint64_t canonp(uint64_t p){return canon(unpack(p));}
inline int tot(uint64_t p){int z=0;for(int i=0;i<12;i++)z+=(p>>(3*i))&7;return z;} unordered_map<uint64_t,double> NC;
double normp(uint64_t p){auto it=NC.find(p);if(it!=NC.end())return it->second;State s=unpack(p);double z=0;for(int i=0;i<12;i++)for(int j=0;j<12;j++)z+=s[i]*G[i][j]*s[j];return NC[p]=z;}
struct R{double pure,imp;uint64_t pA=0,pB=0,iA=0,iB=0;int iMode=-1;}; unordered_map<uint64_t,R> MEM;
R solve(uint64_t pc);
void rec(const State&c,uint64_t pc,int idx,int rem,State&a,R &best){
 if(idx==12){if(rem)return;State b{};for(int k=0;k<12;k++)b[k]=c[k]-a[k];uint64_t pa=pack(a),pb=pack(b);if(pa>pb)return;uint64_t ca=canonp(pa),cb=canonp(pb);R A=solve(ca),B=solve(cb);double d=(2*normp(pa)+2*normp(pb)-normp(pc))/tot(pc);bool even=true;for(int k=0;k<12;k++)if(c[k]&1)even=false;
  if(even && isfinite(A.pure)&&isfinite(B.pure)){double e=d+2*(A.pure+B.pure);if(e<best.pure){best.pure=e;best.pA=ca;best.pB=cb;}}
  auto upd=[&](double x,int mode){if(isfinite(x)){double e=d+2*x;if(e<best.imp){best.imp=e;best.iA=ca;best.iB=cb;best.iMode=mode;}}};
  if(!even && isfinite(A.pure)&&isfinite(B.pure))upd(A.pure+B.pure,0);
  if(isfinite(A.imp)&&isfinite(B.pure))upd(A.imp+B.pure,1);
  if(isfinite(A.pure)&&isfinite(B.imp))upd(A.pure+B.imp,2);
  if(isfinite(A.imp)&&isfinite(B.imp))upd(A.imp+B.imp,3);
  return;}
 int tail=0;for(int k=idx+1;k<12;k++)tail+=c[k];for(int v=max(0,rem-tail);v<=min<int>(c[idx],rem);v++){a[idx]=v;rec(c,pc,idx+1,rem-v,a,best);}a[idx]=0;
}
R solve(uint64_t pc){auto it=MEM.find(pc);if(it!=MEM.end())return it->second;int m=tot(pc);if(m==1){R r;r.pure=0;r.imp=INFINITY;return MEM[pc]=r;}State c=unpack(pc),a{};R best;best.pure=INFINITY;best.imp=INFINITY;rec(c,pc,0,m/2,a,best);bool even=true;for(auto x:c)if(x&1)even=false;if(!even)best.pure=INFINITY;return MEM[pc]=best;}
void trace_imp(uint64_t pc,int depth=0){R r=solve(pc);State c=unpack(pc);cerr<<string(depth,' ')<<"m="<<tot(pc)<<" c=";for(auto x:c)cerr<<(int)x<<",";cerr<<" imp="<<r.imp<<" mode="<<r.iMode<<"\n";if(r.iMode==0){cerr<<string(depth,' ')<<"MIXED_CHERRY ";for(int i=0;i<12;i++)if(c[i])cerr<<i<<":"<<(int)c[i]<<" ";cerr<<"\n";return;}if(r.iMode==1||r.iMode==3)trace_imp(r.iA,depth+1);if(r.iMode==2||r.iMode==3)trace_imp(r.iB,depth+1);}
int main(int argc,char**argv){int mask=argc>1?atoi(argv[1]):15;State r{};r.fill(2);for(int i=0;i<12;i++)if(mask&(1<<i))r[i]=4;auto t=chrono::steady_clock::now();R x=solve(canon(r));double sec=chrono::duration<double>(chrono::steady_clock::now()-t).count();cout<<setprecision(17)<<"mask "<<mask<<" pure "<<x.pure<<" impurity "<<x.imp<<" gap "<<x.imp-x.pure<<" scaled_gap_half "<<(x.imp-x.pure)/2<<" states "<<MEM.size()<<" sec "<<sec<<"\n";trace_imp(canon(r));}
